#include "nf_smart18b1.h"
#include <assert.h>
#include <stdio.h>
static uint32_t rnd(uint32_t *s){*s=1664525u*(*s)+1013904223u;return *s;}
int main(void){size_t passed=0;for(unsigned seed=1;seed<=6000;seed++){NfB1World w;nf_b1_init(&w);w.tick=seed;w.world_revision=seed*5u;uint32_t state=seed;NfB1Object o={.id=10,.material_identity_epoch=27,.material_revision=1,.owner=7,.locked=(uint8_t)(rnd(&state)&1u),.open=0,.material_known=(uint8_t)(rnd(&state)&1u),.support_valid=(uint8_t)(rnd(&state)&1u)};assert(nf_b1_add(&w,o));NfB1Intent i={.actor_id=(rnd(&state)&1u)?7u:8u,.object_id=10,.tick=seed,.expected_revision=w.world_revision,.observed_material_epoch=27,.action=NF_B1_OPEN,.physically_reachable=(uint8_t)(rnd(&state)&1u),.clearance=(uint8_t)(rnd(&state)&1u),.has_contract=(uint8_t)(rnd(&state)&1u),.actor_observed=(uint8_t)(rnd(&state)&1u)};NfB1World unchanged=w;NfB1Decision d=nf_b1_evaluate(&w,&i),replay=nf_b1_evaluate(&w,&i);assert(d.status==replay.status&&d.witness==replay.witness);if(d.status!=NF_B1_OK){assert(nf_b1_commit(&w,&i,d)!=NF_B1_OK);assert(w.world_revision==unchanged.world_revision&&w.event_count==0);passed++;continue;}assert(nf_b1_commit(&w,&i,d)==NF_B1_OK);assert(w.event_count==1&&w.objects[0].open&&w.world_revision==unchanged.world_revision+1);assert(w.objects[0].material_identity_epoch==27);assert(nf_b1_commit(&w,&i,d)!=NF_B1_OK);passed++;}NfB1World w;nf_b1_init(&w);w.tick=3;NfB1Object o={.id=10,.material_identity_epoch=27,.material_known=1,.support_valid=1};assert(nf_b1_add(&w,o));NfB1Intent i={.actor_id=7,.object_id=10,.tick=3,.observed_material_epoch=27,.action=NF_B1_OPEN,.physically_reachable=1,.clearance=1,.has_contract=1,.actor_observed=1};NfB1Decision d=nf_b1_evaluate(&w,&i);w.event_count=NF_B1_MAX_EVENTS;assert(nf_b1_commit(&w,&i,d)==NF_B1_FULL);assert(!w.objects[0].open&&w.world_revision==0);puts("clean_reproduction_1.8B.1: 6000 deterministic seed fixtures + capacity gate PASS (not historical M0-M4 corpus)");printf("cases=%zu\n",passed);return 0;}
